import{z as d,x as B,o as t,c as p,q as o,j as s,D as e,d as r,s as i,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"库内死锁","description":"","frontmatter":{"title":"库内死锁","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/db-deadlock.md","filePath":"cs/db-deadlock.md","lastUpdated":1791413859000}'),A={name:"cs/db-deadlock.md"};function T(m,a,C,c,f,D){const l=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=o('<h1 id="库内死锁" tabindex="-1">库内死锁 <a class="header-anchor" href="#库内死锁" aria-label="Permalink to &quot;库内死锁&quot;">​</a></h1><div class="epigraph"><p>事务锁上的等待可以成环；库检测环并回滚其中一人，与操作系统的四条件同一结构、另一套对象。</p><footer>—— 对照[死锁四个条件](/cs/deadlock-coffman)；Gray and Reuter 对等待图的整理</footer></div><p><a href="/cs/isolation-levels">上一课</a>让事务为隔离而持锁或等待版本冲突。本课不重列异常名。<a href="/cs/deadlock-coffman">Coffman 四条件</a>已在操作系统课钉过。缺口是：数据库的锁是数据项上的、可升级、可超时，等待图在锁管理器里，而不是进程对设备。库通常<strong>检测并牺牲</strong>，很少靠银行家算法预防。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(T_1\\) 持有 \\(x\\) 等 \\(y\\)，\\(T_2\\) 持有 \\(y\\) 等 \\(x\\)，环出现。缺口不是再证四条件，而是把对象换成事务与锁：互斥（X）、占有并等待、不可抢占（一般不抢锁）、循环等待。检测：周期建等待图或在加边时判环。牺牲：abort 代价较小或年轻的事务，其 UNDO 走<a href="/cs/aries-recovery">ARIES</a>。</p><p><span class="marginnote">等待图像一张「谁在等谁」的欠条网：每个事务挂一张「我等 T2 放手」的欠条。沿着欠条走一圈回到自己，就是死锁；图上没环，顶多算慢，有环才彻底没人能动。</span></p><p><span class="marginnote">闩锁（页内短锁）死锁由引擎自己保证无环或有固定顺序；事务死锁才进等待图。两者不要混成一句「数据库死锁」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>等待图：顶点事务，边「等谁」。有环则选受害者。超时是粗糙检测，可能误杀慢事务。预防：按对象序加锁、wait-die / wound-wait 时间戳，应用难守全序，故引擎以检测为主。本课不把分布式死锁的幽灵边写完，只点名：两阶段提交等待也会跨节点成环。</p><p><span class="marginnote">wait-die 用数字看：老事务（时间戳小）允许等新事务手里的锁；新事务撞上老事务就立刻放弃重来。把方向反过来就是 wound-wait：老事务直接叫停挡路的新事务。两者都用「年龄」破环，区别只在谁让谁。</span></p>',10)),(t(),s(n,null,{default:e(()=>[i(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20WAIT%5B%22%E9%94%81%E7%AD%89%E5%BE%85%22%5D%20--%3E%20WG%5B%22%E7%AD%89%E5%BE%85%E5%9B%BE%22%5D%0A%20%20WG%20--%3E%7C%22%E6%9C%89%E7%8E%AF%22%7C%20ABRT%5B%22abort%20%E5%8F%97%E5%AE%B3%E8%80%85%22%5D%0A%20%20ABRT%20--%3E%20UNDO%5B%22WAL%20UNDO%22%5D%0A%20%20WG%20--%3E%20TPC%5B%22%E5%90%8E%E8%AF%BE%3A%20%E4%B8%A4%E9%98%B6%E6%AE%B5%E6%8F%90%E4%BA%A4%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"隔离级别影响环的频率：锁越长、粒度越粗，环越多。MVCC 减少读写等待，写写仍可环。受害者回滚释放锁，环断，其余前进；被牺牲者由应用重试，可能再次撞上热点——这是活锁边界，不是检测失败。",-1)),a[5]||(a[5]=E("p",null,"死锁不是完整性错误：约束仍成立，只是进度卡住。日志必须记下 abort，以免恢复把半成品重做提交。",-1)),a[6]||(a[6]=E("p",null,"环是怎么形成的，以及谁来破环：",-1)),(t(),s(n,null,{default:e(()=>[i(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1A%5B%22T1%20%E5%B7%B2%E6%8C%81%E6%9C%89%20x%20%E7%9A%84%E9%94%81%22%5D%20--%3E%20T1W%5B%22T1%20%E8%AF%B7%E6%B1%82%20y%EF%BC%9A%E6%8E%92%E9%98%9F%E7%AD%89%20T2%20%E6%94%BE%E6%89%8B%22%5D%0A%20%20T2A%5B%22T2%20%E5%B7%B2%E6%8C%81%E6%9C%89%20y%20%E7%9A%84%E9%94%81%22%5D%20--%3E%20T2W%5B%22T2%20%E8%AF%B7%E6%B1%82%20x%EF%BC%9A%E6%8E%92%E9%98%9F%E7%AD%89%20T1%20%E6%94%BE%E6%89%8B%22%5D%0A%20%20T1W%20--%3E%20CYC%5B%22%E7%AD%89%E5%BE%85%E5%9B%BE%E6%88%90%E7%8E%AF%EF%BC%9AT1%20%E5%88%B0%20T2%20%E5%86%8D%E5%9B%9E%20T1%22%5D%0A%20%20T2W%20--%3E%20CYC%0A%20%20CYC%20--%3E%20VICT%5B%22%E5%BC%95%E6%93%8E%E9%80%89%E4%B8%AD%E5%8F%97%E5%AE%B3%E8%80%85%E5%9B%9E%E6%BB%9A%E5%B9%B6%E9%87%8A%E6%94%BE%E5%85%B6%E9%94%81%22%5D%0A%20%20VICT%20--%3E%20GO%5B%22%E5%8F%A6%E4%B8%80%E4%BA%8B%E5%8A%A1%E6%8B%BF%E5%88%B0%E9%94%81%E7%BB%A7%E7%BB%AD%E5%89%8D%E8%BF%9B%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">初学者容易把死锁当成数据坏了。实际上死锁不违反任何约束：钱没多没少，只是两个事务都卡着不动；引擎回滚一个，数据库依旧一致。真正要紧的是应用收到「被选为受害者」后必须重试，否则那条业务就悄悄失败了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把死锁当「锁用错了」的道德判断；可串行协议几乎必然允许等待。也不讲应用层的重试风暴治理。单对象无等待的 OCC 用中止换阻塞，死锁少、中止多，是另一权衡。</p><p>检测周期太长，吞吐先冻住；太短则空耗 CPU。这是参数，不是新协议。后课默认：单机锁死锁可检测；跨资源管理器的原子提交是另一协议，失败模式从环变成协调器阻塞。</p><p>牺牲者必须真的 abort 并释放，环才会断。只超时不 UNDO，等待图仍在。这与 OS 里杀进程同一结构。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>闩锁死锁由引擎内部顺序避免；事务死锁才进等待图，二者不要混名。</p></li><li><p>后课 2PC 的等待跨节点，检测图会变成分布式。</p></li><li><p>隔离带来等待；库内死锁 = 事务等待图成环，牺牲一人。</p></li><li><p>与 OS 四条件同构，对象是锁项，处理以检测为主。</p></li><li><p>跨库原子提交不能靠这一张等待图，入口是两阶段提交。</p></li><li><p>出处：Gray and Reuter；对照 Coffman et al.；Bernstein 并发控制。</p></li></ul>',7))])}const _=d(A,[["render",T]]);export{h as __pageData,_ as default};
